  const runFailingTurn = async (reason: unknown) => {
    let receivedError: Error | undefined;
    let callCount = 0;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        callCount++;
        receivedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(createErrorProvider(reason), promptBuilder, undefined, {hooks});
    const thrown = await orchestrator.processMessage(createSession('hello')).catch((caught: unknown) => caught);
    return {callCount, receivedError, thrown};
  };

  it('wraps a thrown plain object in an Error preserving the original object as cause', async () => {
    const reason = {code: 503, detail: 'upstream down'};
    const {callCount, receivedError, thrown} = await runFailingTurn(reason);

    expect({
      callCount,
      isError: receivedError instanceof Error,
      hasReadableMessage: typeof receivedError?.message === 'string' && receivedError.message.length > 0,
      sameCause: receivedError?.cause === reason,
      sameThrown: thrown === reason,
    }).toEqual({
      callCount: 1,
      isError: true,
      hasReadableMessage: true,
      sameCause: true,
      sameThrown: true,
    });
  });

  it('wraps a thrown undefined in an Error with cause undefined while rethrowing undefined', async () => {
    const {callCount, receivedError, thrown} = await runFailingTurn(undefined);

    expect({
      callCount,
      isError: receivedError instanceof Error,
      message: receivedError?.message,
      hasCauseProp: receivedError !== undefined && 'cause' in receivedError,
      cause: receivedError?.cause,
      thrown,
    }).toEqual({
      callCount: 1,
      isError: true,
      message: 'undefined',
      hasCauseProp: true,
      cause: undefined,
      thrown: undefined,
    });
  });

  it('passes an Error instance directly to onError as the same instance', async () => {
    const original = new Error('original boom');
    const {callCount, receivedError, thrown} = await runFailingTurn(original);

    expect({
      callCount,
      sameErrorInstance: receivedError === original,
      sameThrownInstance: thrown === original,
    }).toEqual({
      callCount: 1,
      sameErrorInstance: true,
      sameThrownInstance: true,
    });
  });
});

